# Final verification of what I called "spiral sort"
input_grid = [[6, 1, 0], [4, 8, 9], [2, 7, 3]]

def spiral_read(grid):
    result = []
    top, bottom = 0, len(grid) - 1
    left, right = 0, len(grid[0]) - 1

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            result.append(grid[top][col])
        top += 1
        for row in range(top, bottom + 1):
            result.append(grid[row][right])
        right -= 1
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(grid[bottom][col])
            bottom -= 1
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(grid[row][left])
            left += 1
    return result

def spiral_write(grid_size, values):
    result = [[0] * grid_size for _ in range(grid_size)]
    top, bottom = 0, grid_size - 1
    left, right = 0, grid_size - 1
    idx = 0

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            result[top][col] = values[idx]
            idx += 1
        top += 1
        for row in range(top, bottom + 1):
            result[row][right] = values[idx]
            idx += 1
        right -= 1
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result[bottom][col] = values[idx]
                idx += 1
            bottom -= 1
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result[row][left] = values[idx]
                idx += 1
            left += 1
    return result

